{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "title": "animation.animator add_transition",
  "description": "Add a transition between two states (or from AnyState/Entry, to Exit) on a layer, with optional conditions. Validates that the states exist and each condition's parameter exists and its mode matches the parameter type.",
  "properties": {
    "controller": {
      "type": "string",
      "description": "Reference to the AnimatorController to edit (path / guid / globalId)."
    },
    "layer": {
      "type": "string",
      "description": "Layer index (int) or name (string). Default 0 (Base Layer)."
    },
    "from-state": {
      "type": "string",
      "description": "Source state name, or the special \"AnyState\" / \"Entry\"."
    },
    "to-state": {
      "type": "string",
      "description": "Destination state name, or the special \"Exit\"."
    },
    "conditions": {
      "type": "string",
      "description": "Optional conditions: [{ parameter, mode: \"If\"|\"IfNot\"|\"Greater\"|\"Less\"|\"Equals\"|\"NotEqual\", threshold? }]."
    },
    "has-exit-time": {
      "type": "boolean",
      "description": "If true, the transition uses exit time (default false).",
      "default": false
    },
    "exit-time": {
      "type": "number",
      "description": "Normalized exit time (0..1) when has-exit-time is set.",
      "default": 0.0
    },
    "duration": {
      "type": "number",
      "description": "Transition duration in seconds (default 0.25).",
      "default": 0.25
    },
    "has-fixed-duration": {
      "type": "boolean",
      "description": "If true, duration is in seconds; otherwise normalized (default true).",
      "default": true
    },
    "dry-run": {
      "type": "boolean",
      "description": "If true, validate everything (states, parameters, mode/type) without writing the transition.",
      "default": false
    }
  },
  "required": [
    "controller",
    "from-state",
    "to-state"
  ],
  "additionalProperties": false,
  "x-command-metadata": {
    "mainThreadRequired": true,
    "methodName": "Unity.Pipeline.Editor.Commands.Animation.AnimatorControllerCommands.AddTransition"
  }
}

